"""Revised Hindi writing course. Required literature is distinct from extra health material."""


def text(value, kind="paragraph", heading=None):
    return {"kind": kind, "text": value, "heading": heading}


def section(heading, *blocks):
    return {"heading": heading, "blocks": list(blocks)}


def topic(slug, title, order, subtitle, sections, tags):
    return {"slug": slug, "unit": 1, "title": title, "order": order, "subtitle": subtitle,
            "icon": "PenLine", "read_minutes": 8, "tags": tags, "sections": sections}


